26	// Build a ForFrame that emits a target-neutral kThreadBinding loop for one
27	// kernel-launch dimension. The launch nest is materialized into the
28	// target-specific form (thread_extent AttrStmt on GPU, serial For on CPU) by
29	// the tl.MaterializeKernelLaunch pass once the Target is known at compile
30	// time.
31	static ForFrame MakeThreadBindingFrame(const std::string &name,
32	                                       const String &thread_tag,
33	                                       const PrimExpr &extent) {
34	  using namespace tvm::tirx;
35	  Var var = Var(name, extent->dtype);
36	  ObjectPtr<ForFrameNode> n = make_object<ForFrameNode>();
37	  n->vars.push_back(var);
38	  n->doms.push_back(Range(make_const(extent->dtype, 0), extent));
39	  n->f_make_for_loop =
40	      [thread_tag](const Array<Var> &vars, const Array<Range> &doms,
41	                   const Array<Optional<PrimExpr>> &steps, Stmt body) -> Stmt {
42	    ICHECK_EQ(vars.size(), 1);
43	    ICHECK_EQ(doms.size(), 1);
44	    IterVar iter_var(Range{nullptr}, Var(thread_tag, vars[0]->dtype),
45	                     IterVarType::kThreadIndex, thread_tag);
46	    Optional<PrimExpr> step =
47	        !steps.empty() ? steps[0] : Optional<PrimExpr>(std::nullopt);
48	    return For(vars[0], doms[0]->min, doms[0]->extent, ForKind::kThreadBinding,
49	               body,
50	               /*thread_binding=*/iter_var,
51	               /*annotations=*/Map<String, Any>{},
52	               /*step=*/step);
53	  };
54	  return ForFrame(n);
55	}
