57	ForFrame ParallelFor(const Array<PrimExpr> &extents,
58	                     const Map<String, Any> &annotations) {
59	  using namespace tvm::tirx;
60	  ObjectPtr<ForFrameNode> n = make_object<ForFrameNode>();
61	  n->vars.reserve(extents.size());
62	  n->doms.reserve(extents.size());
63	  for (const auto &extent : extents) {
64	    DataType dtype = extent.dtype();
65	    n->vars.push_back(Var("v", extent.dtype()));
66	    n->doms.push_back(Range(make_const(dtype, 0), extent));
67	  }
68	  n->f_make_for_loop =
69	      [annotations](const Array<Var> &vars, const Array<Range> &doms,
70	                    const Array<Optional<PrimExpr>> &steps, Stmt body) -> Stmt {
71	    ICHECK_EQ(vars.size(), doms.size());
72	    int n = vars.size();
73	    for (int i = n - 1; i >= 0; --i) {
74	      Range dom = doms[i];
75	      Var var = vars[i];
76	      Optional<PrimExpr> step =
77	          i < steps.size() ? steps[i] : Optional<PrimExpr>(std::nullopt);
78	      // Only attach annotations to the outermost parallel loop.
79	      // Rationale: In TileLang's design, inner loops cannot govern or annotate
80	      // their outer loops, while the outermost loop can manage and transform
81	      // the entire nested region. Placing the layout on the outermost loop
82	      // lets lowering/validators reason about and rewrite the whole nest.
83	      // Layout annotations (like parallel_loop_layout) and other hints are
84	      // read from the outermost loop.
85	      Map<String, Any> loop_annotations;
86	      if (i == 0) {
87	        loop_annotations = annotations;
88	      }
89	      body = For(var, dom->min, dom->extent, ForKind::kParallel, body,
90	                 /*thread_binding=*/std::nullopt,
91	                 /*annotations=*/loop_annotations,
92	                 /*step=*/step);
93	    }
94	    return body;
95	  };
96	  return ForFrame(n);
97	}
