47	int64_t GetElementStorageBits(DataType dtype) {
48	  // Layout aliasing must be reasoned about in logical storage bits per element,
49	  // not in bytes.  For sub-byte dtypes such as fp4, `dtype.bytes()` rounds up
50	  // to 1 and loses the "two fp4 values share one byte" relationship that
51	  // subtype-changing views rely on.
52	  return static_cast<int64_t>(dtype.bits()) * dtype.lanes();
53	}
