55	bool ShapesEqual(const Array<PrimExpr> &lhs, const Array<PrimExpr> &rhs,
56	                 arith::Analyzer *analyzer) {
57	  if (lhs.size() != rhs.size()) {
58	    return false;
59	  }
60	  for (size_t i = 0; i < lhs.size(); ++i) {
61	    if (!analyzer->CanProveEqual(lhs[i], rhs[i])) {
62	      return false;
63	    }
64	  }
65	  return true;
66	}
