1	/*!
2	 * \file materialize_kernel_launch.cc
3	 * \brief Materialize the target-neutral kernel launch nest emitted by
4	 *        T.Kernel into a backend-specific form.
5	 *
6	 * T.Kernel traces into a nest of For loops with ForKind::kThreadBinding
7	 * tagged blockIdx.* / threadIdx.*. This pass runs right after BindTarget
8	 * and rewrites the nest according to `lower_thread_binding`, which each
9	 * backend pipeline chooses for itself (no target dispatch happens here):
10	 *  - lower_thread_binding = true (SIMT backends, e.g. CUDA/ROCm/Metal):
11	 *    each launch loop becomes an AttrStmt thread_extent, reusing the loop
12	 *    variable so body references stay valid.
13	 *  - lower_thread_binding = false (backends without SIMT, e.g. CPU):
14	 *    blockIdx.* loops become serial For loops over the grid extent;
15	 *    threadIdx.* loops are ignored; they become unit serial loops so the
16	 *    loop variable stays defined (pinned to 0) while the requested thread
17	 *    extent (e.g. the default threads=128) is dropped.
18	 *
19	 * Only the outermost contiguous launch nest is converted; thread_binding
20	 * loops deeper inside the kernel body (separated by the tilelang_root
21	 * block) are left for LowerOpaqueBlock to handle at its usual stage.
22	 */
23	
24	#include "common/attr.h"
25	#include "support/check.h"
26	#include <tvm/ir/transform.h>
27	#include <tvm/runtime/logging.h>
28	#include <tvm/tirx/stmt_functor.h>
29	#include <tvm/tirx/transform.h>
30	
31	#include <utility>
32	
33	namespace tvm {
34	namespace tl {
35	
36	using namespace tirx;
37	
38	namespace {
39	
40	bool IsBlockBinding(const ForNode *op) {
41	  if (op->kind != ForKind::kThreadBinding || !op->thread_binding.defined())
42	    return false;
43	  std::string tag = op->thread_binding.value()->thread_tag;
44	  return tag.rfind("blockIdx.", 0) == 0;
45	}
46	
47	bool IsThreadBinding(const ForNode *op) {
48	  if (op->kind != ForKind::kThreadBinding || !op->thread_binding.defined())
49	    return false;
50	  std::string tag = op->thread_binding.value()->thread_tag;
51	  return tag.rfind("threadIdx.", 0) == 0;
52	}
53	
54	bool IsLaunchBinding(const ForNode *op) {
55	  return IsBlockBinding(op) || IsThreadBinding(op);
56	}
57	
58	class KernelLaunchMaterializer : public StmtMutator {
59	public:
60	  explicit KernelLaunchMaterializer(bool lower_thread_binding)
61	      : lower_thread_binding_(lower_thread_binding) {}
62	
63	  Stmt VisitStmt_(const ForNode *op) final {
64	    if (IsLaunchBinding(op)) {
65	      return ConvertNest(op);
66	    }
67	    return StmtMutator::VisitStmt_(op);
68	  }
69	
70	private:
71	  // Peel the contiguous launch nest rooted at `op` without descending into
72	  // the kernel body below it.
73	  Stmt ConvertNest(const ForNode *op) {
74	    Stmt body;
75	    if (const ForNode *inner = op->body.as<ForNode>();
76	        inner && IsLaunchBinding(inner)) {
77	      body = ConvertNest(inner);
78	    } else {
79	      body = op->body;
80	    }

